########################################################################
# Affine semigroups
# 
# An affine semigroup is a subset `Q = ⟨v₁, …, vₘ⟩⊂ ℤᵈ` generated by 
# the elements `vᵢ` over `ℕ₀`. It is called *saturated* if 
#
#   Q = ℤ ⋅Q ∩ ℝ₊Q, where ℝ₊ = {x ∈ ℝ : x ≥ 0}.
#
# Saturated semigroups can be described by polyhedral cones 
# rather than generators, but this is not true in general. 
#
# Example: `Q = ⟨[2], [3]⟩ ⊂ ℤ¹` and `1 ∉ Q`, hence `Q` is not saturated. 
# 
# 
########################################################################
@attributes mutable struct AffineSemigroup{T} # affine semigroup
  ambient_group::FinGenAbGroup # the ambient ℤᵈ
  generators::MatElem{T}

  function AffineSemigroup(generators::MatElem{T}; ambient_group::FinGenAbGroup=free_abelian_group(ncols(generators))) where T <: ZZRingElem
    @assert is_free(ambient_group) && rank(ambient_group) == ncols(generators) "incompatible ambient group"
    return new{T}(ambient_group, generators)
  end
  function AffineSemigroup(P::Cone{QQFieldElem}; ambient_group::FinGenAbGroup=free_abelian_group(ambient_dim(P)))
    @assert is_pointed(P) "at the moment we only support construction of affine semigroups from pointed polyhedral cones"
    @assert is_free(ambient_group) && rank(ambient_group) == ambient_dim(P) "incompatible ambient group"
    res = new{ZZRingElem}(ambient_group)
    set_attribute!(res, :polyhedral_cone, P)
    return res
  end
end

function Base.show(io::IO, S::AffineSemigroup)
  print(io, "Affine semigroup in ambient dimension ", ambient_dim(S))
end

function Base.show(io::IO, ::MIME"text/plain", S::AffineSemigroup)
  println(io, "Affine semigroup in ambient dimension ", ambient_dim(S), " generated by")
  print(io, "  ", join(string.(gens(S)), "\n  "))
end

function _generator_matrix(Q::AffineSemigroup)
  if !isdefined(Q, :generators)
    C = polyhedral_cone(Q)
    hb = hilbert_basis(C)
    m = length(hb)
    n = ambient_dim(C)
    Q.generators = matrix_space(ZZ, m, n)(transpose(reduce(hcat, [Vector{ZZRingElem}(v) for v in hb])))
  end
  return Q.generators
end

function ambient_group(Q::AffineSemigroup)
  return Q.ambient_group
end

function gens(::Type{T}, Q::AffineSemigroup) where {T<:Vector}
  M = _generator_matrix(Q)
  return T[M[i, :] for i in 1:nrows(M)]
end

function Oscar.gen(::Type{T}, Q::AffineSemigroup, i::Int) where {T<:Vector}
  return T(_generator_matrix(Q)[i, :])
end

function gens(Q::AffineSemigroup)
  F = ambient_group(Q)
  M = _generator_matrix(Q)
  return [F(M[i, :]) for i in 1:nrows(M)]
end

function Oscar.gen(Q::AffineSemigroup, i::Int)
  F = ambient_group(Q)
  return F(_generator_matrix(Q)[i, :])
end

@attr Int function rank(Q::AffineSemigroup)
  return rank(_generator_matrix(Q))
end

# dimension d of the lattice ZZ^d containing Q
function Oscar.ambient_dim(Q::AffineSemigroup)
  isdefined(Q, :generators) && return ncols(_generator_matrix(Q))
  return ambient_dim(polyhedral_cone(Q))
end

@doc raw"""
    affine_semigroup(M::Matrix{Int})
    affine_semigroup(V::Vector{Vector{Int}})

Create the affine semigroup generated by the columns of the integer matrix `M`,
respectively by the integer vectors in `V`.
"""
function affine_semigroup(M::Matrix{Int}; ambient_group::FinGenAbGroup=free_abelian_group(ncols(M)))
  return AffineSemigroup(matrix_space(ZZ, size(M)...)(M); ambient_group)
end

function affine_semigroup(M::MatElem{T}; ambient_group::FinGenAbGroup=free_abelian_group(ncols(M))) where T
  return AffineSemigroup(map_entries(ZZ, M); ambient_group)
end

function affine_semigroup(M::MatElem{T}; ambient_group::FinGenAbGroup=free_abelian_group(ncols(M))) where {T <: ZZRingElem}
  return AffineSemigroup(M; ambient_group)
end

function affine_semigroup(V_Q::Vector{Vector{Int}}; ambient_group::FinGenAbGroup=free_abelian_group(length(first(V_Q))))
  @assert !is_empty(V_Q) "list of generators must not be empty"
  m = length(V_Q)
  n = length(first(V_Q))
  @assert all(length(v) == n for v in V_Q) "all vectors must have the same length"
  return affine_semigroup(matrix_space(ZZ, m, n)(reduce(vcat, V_Q)); ambient_group)
end

# elements in semigroups
mutable struct AffineSemigroupElem{T}
  parent::AffineSemigroup{T}
  coords::Union{Vector{T}, Nothing}
  repres::Union{FinGenAbGroupElem, Nothing}

  # constructor for the zero element
  function AffineSemigroupElem(Q::AffineSemigroup{T}) where T
    return new{T}(Q, nothing, nothing)
  end

  # constructor from a linear combination of the generators
  function AffineSemigroupElem(Q::AffineSemigroup{T}, coords::Vector{ZZRingElem}) where {T}
    @assert length(coords) == nrows(_generator_matrix(Q)) "coordinate vector does not have the same length as the generating set"
    return new{T}(Q, coords, nothing)
  end

  # constructor from a representative in the ambient group
  function AffineSemigroupElem(Q::AffineSemigroup{T}, repres::FinGenAbGroupElem; check::Bool=true) where {T}
    @assert parent(repres) === ambient_group(Q) "parent mismatch"
    @check ZZRingElem[repres[i] for i in 1:ngens(parent(repres))] in polyhedral_cone(Q) "representative does not lay in the semigroup"
    return new{T}(Q, nothing, repres)
  end
end 

parent(v::AffineSemigroupElem) = v.parent

function Oscar.coordinates(v::AffineSemigroupElem)
  if isnothing(v.coords)
    # TODO: compute the coordinates
  end
  return v.coords::Vector{ZZRingElem}
end

function is_zero(v::AffineSemigroupElem)
  isnothing(v.coords) && isnothing(v.repres) && return true
  return is_zero(repres(v))
end

function Oscar.repres(v::AffineSemigroupElem)
  isnothing(v.coords) && isnothing(v.repres) && return zero(ambient_group(parent(v)))
  if isnothing(v.repres)
    F = ambient_group(parent(v))
    if !isnothing(v.coords)
      v.repres = sum(a*gen(Q, i) for (i, a) in enumerate(coordinates(v)); init=zero(F))
    else
      v.repres = zero(F)
    end
  end
  return v.repres::FinGenAbGroupElem
end

function (Q::AffineSemigroup)()
  return AffineSemigroupElem(Q)
end

function (Q::AffineSemigroup)(v::FinGenAbGroupElem)
  return AffineSemigroupElem(Q, v)
end

function Base.show(io::IO, v::AffineSemigroupElem)
  print(io, repres(v))
end

function Base.show(io::IO, ::MIME"text/plain", v::AffineSemigroupElem)
  print(io, repres(v))
end

function Oscar.addmul!(v::AffineSemigroupElem, w::AffineSemigroupElem, c)
  return addmul!(v, w, ZZ(c))
end

function Oscar.addmul!(v::AffineSemigroupElem, w::AffineSemigroupElem, c::ZZRingElem)
  is_zero(w) && return v
  is_zero(c) && return v
  if !isnothing(v.coords) && !isnothing(w.coords)
    v.coords .+= c*w.coords
    v.repres = nothing
    return v
  end
  if is_zero(v) 
    if !isnothing(w.coords)
      v.coords = c*w.coords
      v.repres = nothing
      return v
    end
    v.repres = c*w.repres
    v.coords = nothing
    return v
  end
  v.repres = addmul!(repres(v), repres(w), c)
  v.coords = nothing
  return v
end

function Oscar.mul!(v::AffineSemigroupElem, c)
  return mul!(v, ZZ(c))
end

function Oscar.mul!(v::AffineSemigroupElem, c::ZZRingElem)
  iszero(v) && return v
  if !isnothing(v.coords)
    v.coords .*= c
    return v
  end
  v.repres = mul!(v.repres, c)
  return v
end

function +(v::AffineSemigroupElem, w::AffineSemigroupElem)
  return addmul!(deepcopy(v), w, 1)
end

function -(v::AffineSemigroupElem, w::AffineSemigroupElem)
  return addmul!(deepcopy(v), w, -1)
end

function *(c, v::AffineSemigroupElem)
  return ZZ(c)*v
end

function *(c::ZZRingElem, v::AffineSemigroupElem)
  return mul!(deepcopy(v), c)
end

function Base.deepcopy_internal(v::AffineSemigroupElem, dict::IdDict)
  res = parent(v)()
  if !isnothing(v.coords)
    res.coords = deepcopy_internal(v.coords, dict)
  end
  if !isnothing(v.repres)
    res.repres = deepcopy_internal(v.repres, dict)
  end
  return res
end

# properties of semigroups
@doc raw"""
    is_pointed(S::AffineSemigroup)

Check whether the cone of the affine semigroup `S` is pointed.
"""
@attr Bool function Oscar.is_pointed(S::AffineSemigroup)
  return is_pointed(polyhedral_cone(S))
end

@attr Cone{QQFieldElem} function polyhedral_cone(S::AffineSemigroup)
  M = _generator_matrix(S)
  G = [M[i, :] for i in 1:nrows(M)]
  return positive_hull(G)
end

@attr Polyhedron function Oscar.cone(S::AffineSemigroup)
  return polyhedron(polyhedral_cone(S))
end

@attr Vector{HyperplaneQ} function Oscar.hyperplanes(S::AffineSemigroup)
  return get_bounding_hyperplanes(cone(S))
end

@attr Tuple{Polyhedron,Vector{Int}} function Oscar.zonotope(S::AffineSemigroup)
  return get_zonotope(cone(S))
end

function in_milp(v::AbstractVector, S::AffineSemigroup)
  M = _generator_matrix(S)
  m = nrows(M)
  length(v) == ncols(M) || return false
  b = matrix(ZZ, length(v), 1, ZZ.(v))
  sol = solve_mixed(ZZMatrix, transpose(M), b, identity_matrix(ZZ, m), zero_matrix(ZZ, m, 1))
  return nrows(sol) > 0   # or ncols; the docs say solutions are the (transposed) rows
end

@attr Bool function is_saturated(S::AffineSemigroup)
  return all(h -> in_milp(h, S), hilbert_basis(polyhedral_cone(S)))
end

function Base.in(v::AbstractVector{<:IntegerUnion}, S::AffineSemigroup)
  @req length(v) == ambient_dim(S) "the point does not lie in the ambient space"
  v in polyhedral_cone(S) || return false      # necessary condition
  is_saturated(S) && return true
  return in_milp(v, S)
end

